#!/usr/bin/env python3
"""Focused verification for the CVE-2015-3339 port.

This does NOT build the whole kernel. It:
  1. extracts the actual bprm_fill_uid() and prepare_binprm() text from the
     patched fs/exec.c,
  2. asserts the security-relevant ordering/placement invariants statically,
  3. compiles the extracted code with a mock harness using the host gcc
     (-fsyntax-only) to catch syntax/type errors in the modified code.

Usage: focused_exec_check.py <path-to-fs/exec.c>
Exit code 0 iff all checks pass.
"""
from __future__ import annotations

import re
import subprocess
import sys
from pathlib import Path

HELPER_SIG = "static void bprm_fill_uid(struct linux_binprm *bprm)"
PREP_SIG = "int prepare_binprm(struct linux_binprm *bprm)"


def extract_function(text: str, signature: str) -> str:
    start = text.index(signature)
    brace = text.index("{", start)
    depth = 0
    for i in range(brace, len(text)):
        if text[i] == "{":
            depth += 1
        elif text[i] == "}":
            depth -= 1
            if depth == 0:
                return text[start:i + 1]
    raise AssertionError(f"unterminated function {signature!r}")


def check(name: str, condition: bool, detail: str) -> str:
    if not condition:
        raise AssertionError(f"FAIL {name}: {detail}")
    return f"PASS {name}: {detail}"


MOCK_HEADER = r"""
#include <sys/stat.h>
#include <stdbool.h>
#include <stddef.h>

#define ACCESS_ONCE(x) (*(volatile typeof(x) *)&(x))
#define MNT_NOSUID 0x01
#define PER_CLEAR_ON_SETID 0x01
#define BINPRM_BUF_SIZE 128

typedef unsigned int kuid_t;
typedef unsigned int kgid_t;

struct user_namespace { int dummy; };
struct mutex { int locked; };
struct vfsmount { int mnt_flags; };
struct path { struct vfsmount *mnt; };
struct file { struct path f_path; void *f_op; };
struct inode { unsigned short i_mode; kuid_t i_uid; kgid_t i_gid; struct mutex i_mutex; };
struct cred { kuid_t euid; kgid_t egid; struct user_namespace *user_ns; };
struct linux_binprm {
    struct file *file;
    struct cred *cred;
    unsigned int per_clear;
    int cred_prepared;
    char buf[BINPRM_BUF_SIZE];
};
struct task_struct { int no_new_privs; };

extern struct task_struct *current;
extern kuid_t current_euid(void);
extern kgid_t current_egid(void);
extern struct inode *file_inode(struct file *f);
extern bool kuid_has_mapping(struct user_namespace *ns, kuid_t uid);
extern bool kgid_has_mapping(struct user_namespace *ns, kgid_t gid);
extern void mutex_lock(struct mutex *m);
extern void mutex_unlock(struct mutex *m);
extern int security_bprm_set_creds(struct linux_binprm *bprm);
extern int kernel_read(struct file *f, long offset, void *buf, unsigned long count);

int main(void) { return 0; }
"""


def main() -> int:
    if len(sys.argv) != 2:
        print("usage: focused_exec_check.py <fs/exec.c>", file=sys.stderr)
        return 2
    path = Path(sys.argv[1])
    text = path.read_text(encoding="utf-8", errors="replace")
    results: list[str] = []

    helper = extract_function(text, HELPER_SIG)
    prep = extract_function(text, PREP_SIG)

    results.append(check("helper_present", HELPER_SIG in text, "bprm_fill_uid defined"))
    results.append(check("helper_locks_before_reload",
                         helper.index("mutex_lock(&inode->i_mutex)")
                         < helper.index("uid = inode->i_uid;"),
                         "mutex_lock precedes atomic reload of i_uid"))
    results.append(check("helper_lock_scope_covers_reload",
                         helper.index("mutex_lock(&inode->i_mutex)")
                         < helper.index("mode = inode->i_mode;")
                         < helper.index("mutex_unlock(&inode->i_mutex)"),
                         "mode/uid/gid reloaded while i_mutex held"))
    results.append(check("helper_reload_before_assign",
                         helper.index("bprm->cred->euid = uid;")
                         > helper.index("mutex_unlock(&inode->i_mutex)"),
                         "cred assignment uses reloaded locked values"))
    results.append(check("helper_access_once_fastpath",
                         "ACCESS_ONCE(inode->i_mode)" in helper,
                         "ACCESS_ONCE fast path present"))
    results.append(check("helper_nosuid_no_new_privs",
                         "MNT_NOSUID" in helper and "current->no_new_privs" in helper,
                         "MNT_NOSUID and no_new_privs early returns present"))
    results.append(check("helper_mapping_checks",
                         "kuid_has_mapping" in helper and "kgid_has_mapping" in helper,
                         "user_ns mapping checks present"))
    results.append(check("prep_calls_helper",
                         "bprm_fill_uid(bprm);" in prep,
                         "prepare_binprm delegates to bprm_fill_uid"))
    results.append(check("prep_preserves_fop_check",
                         "if (bprm->file->f_op == NULL)" in prep
                         and prep.index("bprm->file->f_op == NULL")
                             < prep.index("bprm_fill_uid(bprm);"),
                         "target-specific f_op==NULL early return preserved before fill"))
    results.append(check("prep_no_unlocked_cred_path",
                         ("= inode->i_uid" not in prep) and
                         ("= inode->i_gid" not in prep) and
                         ("kuid_has_mapping" not in prep) and
                         ("mode = inode->i_mode" not in prep),
                         "old unlocked inline set[ug]id logic fully removed"))
    results.append(check("prep_flow_intact",
                         "security_bprm_set_creds(bprm)" in prep
                         and "bprm->cred_prepared = 1;" in prep
                         and "kernel_read(" in prep,
                         "cred/blob fill and kernel_read flow intact"))

    # Compile the exact extracted functions against mocks.
    source = MOCK_HEADER + "\n" + helper + "\n\n" + prep + "\n"
    tmp = Path(sys.argv[1]).resolve().parent / ".focused_exec_check.c"
    try:
        tmp.write_text(source, encoding="utf-8")
        for compiler in ("/usr/bin/gcc-10", "/usr/bin/gcc-8", "gcc"):
            probe = subprocess.run([compiler, "--version"], capture_output=True, text=True)
            if probe.returncode == 0:
                break
        else:
            raise AssertionError("no host C compiler available")
        comp = subprocess.run(
            [compiler, "-fsyntax-only", "-Wall", "-Wno-unused", str(tmp)],
            capture_output=True, text=True,
        )
        results.append(check("focused_compile", comp.returncode == 0,
                             f"{compiler} -fsyntax-only rc={comp.returncode} "
                             f"{comp.stderr.strip()[:500]}"))
    finally:
        if tmp.exists():
            tmp.unlink()

    print("\n".join(results))
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except AssertionError as exc:
        print(str(exc), file=sys.stderr)
        raise SystemExit(1)

